function validate([n, edges, query]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is an integer from 2 to 100000.';
  if (!Array.isArray(edges) || edges.length > 100000) return 'edges holds at most 100000 edges.';
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 3 || !e.every(Number.isInteger)) return 'Each edge is [u, v, w] with integers.';
    const [u, v, w] = e;
    if (u < 0 || u >= n || v < 0 || v >= n) return 'Edge endpoints are between 0 and n - 1.';
    if (u === v) return 'An edge joins two different vertices.';
    if (w < 0 || w > 100000) return 'Edge weights are between 0 and 100000.';
  }
  if (!Array.isArray(query) || query.length < 1 || query.length > 100000) return 'query needs 1 to 100000 pairs.';
  for (const q of query) {
    if (!Array.isArray(q) || q.length !== 2 || !q.every(Number.isInteger)) return 'Each query is [s, t] with integers.';
    const [s, t] = q;
    if (s < 0 || s >= n || t < 0 || t >= n) return 'Query vertices are between 0 and n - 1.';
    if (s === t) return 'A query names two different vertices.';
  }
  return null;
}

