function minimumCost(n, edges, query) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const cost = new Array(n).fill(-1);

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  for (const [u, v, w] of edges) {
    const rootU = find(u);
    const rootV = find(v);
    if (rootU !== rootV) {
      parent[rootU] = rootV;
      cost[rootV] &= cost[rootU];
    }
    cost[rootV] &= w;
  }

  const answer = [];
  for (const [s, t] of query) {
    const root = find(s);
    if (root !== find(t)) {
      answer.push(-1);
    } else {
      answer.push(cost[root]);
    }
  }
  return answer;
}

