function minimumCost(n, edges, query) {
  // For each query, explore everything reachable from s, then AND every edge inside that region.
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
  return query.map(([s, t]) => {
    const seen = new Set([s]);
    const stack = [s];
    while (stack.length) {
      const x = stack.pop();
      for (const y of adj[x]) if (!seen.has(y)) { seen.add(y); stack.push(y); }
    }
    if (!seen.has(t)) return -1;
    let value = null;
    for (const [u, , w] of edges) if (seen.has(u)) value = value === null ? w : value & w;
    return value;
  });
}

