function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 : 2 + Math.floor(rand() * 6);
  const groups = large ? 1 + Math.floor(rand() * 60) : 1 + Math.floor(rand() * 3);
  const group = Array.from({ length: n }, () => Math.floor(rand() * groups));
  const members = Array.from({ length: groups }, () => []);
  for (let v = 0; v < n; v++) members[group[v]].push(v);
  const masks = Array.from({ length: groups }, () => {
    let mask = 0;
    for (let b = 0; b < 16; b++) if (rand() < 0.3) mask |= 1 << b;
    return mask;
  });
  const edgeCount = large ? 2000 : Math.floor(rand() * 9);
  const edges = [];
  for (let tries = 0; edges.length < edgeCount && tries < edgeCount * 20; tries++) {
    const g = members[Math.floor(rand() * groups)];
    if (g.length < 2) continue;
    const u = g[Math.floor(rand() * g.length)];
    const v = g[Math.floor(rand() * g.length)];
    if (u === v) continue;
    const w = large ? masks[group[u]] | Math.floor(rand() * 65536) : Math.floor(rand() * 16);
    edges.push([u, v, w]);
  }
  const queryCount = large ? 2000 : 1 + Math.floor(rand() * 5);
  const query = [];
  while (query.length < queryCount) {
    const s = Math.floor(rand() * n);
    let t = rand() < 0.6 ? members[group[s]][Math.floor(rand() * members[group[s]].length)] : Math.floor(rand() * n);
    if (s === t) t = (s + 1 + Math.floor(rand() * (n - 1))) % n;
    query.push([s, t]);
  }
  return [n, edges, query];
}
